312	// The closed list of what the recorder may ask for. A manifest or a blob read
313	// through a proxy repository would cache an image and change the bench, so none
314	// is allowed, whatever the path says.
315	var (
316		recordPaths = []*regexp.Regexp{
317			regexp.MustCompile(`^/v2/(_catalog|[a-z0-9._/-]+/tags/list)?$`),
318			regexp.MustCompile(`^/repository/[A-Za-z0-9._-]+/v2/_catalog$`),
319			regexp.MustCompile(`^/service/rest/v1/repositories(/[A-Za-z0-9._-]+)*$`),
320		}
321		recordQueryParam = regexp.MustCompile(`^(n=[0-9]{1,6}|last=[A-Za-z0-9._/-]*)$`)
322	)
323	
324	// refusedRequest returns why a request may not be sent, or "".
325	func refusedRequest(method, target string) string {
326		p, query, hasQuery := strings.Cut(target, "?")
327		switch {
328		case method != http.MethodGet:
329			return "the method is not GET"
330		case strings.Contains(target, "..") || strings.Contains(target, "%"):
331			return "the target holds a dot-dot or an escape"
332		case strings.Contains(p+"/", "/manifests/") || strings.Contains(p+"/", "/blobs/"):
333			return "a manifest or a blob read can change the bench"
334		}
335		listed := false
336		for _, re := range recordPaths {
337			listed = listed || re.MatchString(p)
338		}
339		if !listed {
340			return "the path is not in the closed list"
341		}
342		if hasQuery {
343			for _, param := range strings.Split(query, "&") {
344				if !recordQueryParam.MatchString(param) {
345					return "the query holds more than n and last"
346				}
347			}
348		}
349		return ""
350	}
351	
352	// ---- the data set of the bench ---------------------------------------------------
353	
354	// checkBenchDataset compares, anonymously, what docker-hosted and docker-proxy
355	// list with the data set of the descriptor: a bench that does not hold it would
356	// record answers that are not the ones the fixtures describe. What cannot be read
357	// is a refusal too.
358	func checkBenchDataset(ctx context.Context, o RecordOptions) error {
359		if len(o.Descriptor.Dataset) == 0 {
360			return recordError("the descriptor lists no data set to compare the bench with", "run `mise run nexus-bench:seed`", nil)
361		}
362		key, _ := restOriginKey(o.Descriptor)
363		base := o.Origins[key]
364		for _, repo := range []string{dockerHostedRepository, dockerProxyRepository} {
365			listed, err := ListImagesAnonymously(ctx, base, repo)
366			if err != nil {
367				return recordError("the listing of "+repo+" could not be read, so the data set of the bench is unknown",
368					"check that the bench answers and that anonymous access is on", err)
369			}
370			diffs, ok := compareDataset(datasetIn(o.Descriptor.Dataset, repo), listed)
371			if !ok {
372				return recordError("the listing of "+repo+" gives no digest, so the data set of the bench cannot be compared", resetCheck, nil)
373			}
374			if diffs > 0 {
375				return recordError(fmt.Sprintf("%s differs from the data set of the descriptor (%d image(s))", repo, diffs), resetCheck, nil)
376			}
377		}
378		return nil
379	}
380	
381	// datasetIn returns the images of the data set that repo holds: the hosted ones
382	// in docker-hosted, the ones cached in the proxy in docker-proxy.
383	func datasetIn(images []DescriptorImage, repo string) []DescriptorImage {
384		var out []DescriptorImage
385		for _, img := range images {
386			hosted := repo == dockerHostedRepository && img.Location == string(LocationHosted)
387			cached := repo == dockerProxyRepository && img.CachedInProxy
388			if hosted || cached {
389				out = append(out, img)
390			}
391		}
392		return out
393	}
394	
395	// compareDataset counts the images that are missing, have another digest, or are
396	// not in the data set; ok is false when a listed image has no digest.
397	func compareDataset(want []DescriptorImage, listed []ListedImage) (diffs int, ok bool) {
398		have := make(map[string]string, len(listed))
399		for _, img := range listed {
400			have[img.Name+":"+img.Tag] = img.Digest
401		}
402		for _, img := range want {
403			key := img.Name + ":" + img.Tag
404			digest, found := have[key]
405			delete(have, key)
406			switch {
407			case !found:
408				diffs++
409			case digest == "":
410				return 0, false
411			case digest != img.Digest:
412				diffs++
413			}
414		}
415		return diffs + len(have), true
416	}
