418	// ---- gathering the answers ------------------------------------------------------
419	
420	// gatherAnswers asks every job and returns the files to write and the fixtures
421	// that did not change. The first problem ends the run: nothing is written yet.
422	func gatherAnswers(ctx context.Context, o RecordOptions, jobs []recordJob) (writes []recordWrite, unchanged []string, err error) {
423		clients := map[string]*client{}
424		defer func() {
425			for _, c := range clients {
426				c.closeIdle()
427			}
428		}()
429		now := time.Now
430		if o.Now != nil {
431			now = o.Now
432		}
433		date := now().Format(recordedDateLayout)
434		for _, j := range jobs {
435			key := j.origin + "\x00" + j.user
436			c, ok := clients[key]
437			if !ok {
438				c = newClient(j.origin, j.user, j.password)
439				clients[key] = c
440			}
441			data, same, err := j.record(ctx, o, c, date)
442			switch {
443			case err != nil:
444				return nil, nil, err
445			case same:
446				unchanged = append(unchanged, j.name)
447			default:
448				writes = append(writes, recordWrite{name: j.name, path: j.path, data: data})
449			}
450		}
451		return writes, unchanged, nil
452	}
453	
454	// record asks the bench for the answer of the job and returns the bytes of the
455	// fixture it would write; same is true when the file already holds that answer.
456	func (j recordJob) record(ctx context.Context, o RecordOptions, c *client, date string) (data []byte, same bool, err error) {
457		ex := j.current.Exchanges[0]
458		status, header, body, err := c.exchange(ctx, ex.Method, ex.Target, ex.RequestHeader)
459		if err != nil {
460			return nil, false, recordError("the answer to "+j.name+" could not be read", "check that the bench answers on its loopback ports", err)
461		}
462		if !benchVersionMatches(header.Get("Server"), o.Descriptor) {
463			return nil, false, recordError("the answer to "+j.name+" does not come from the Nexus version and edition the descriptor names", benchUpCall, nil)
464		}
465		if declaresJSON(header.Get("Content-Type")) && len(body) > 0 && !json.Valid(body) {
466			return nil, false, recordError("the answer to "+j.name+" is declared JSON and is not", "do not record this answer: a secret could hide from the redaction in it", nil)
467		}
468		answer := nexusfixture.Redact(nexusfixture.RawExchange{
469			Method: ex.Method, Target: ex.Target, Host: ex.Host, RequestHeader: ex.RequestHeader,
470			Status: status, Header: header, Body: body,
471		})
472		if answer.Stub == "" && answer.Header.Get("Content-Length") != "" {
473			// A redacted body is not as long as the one Nexus sent.
474			answer.Header.Set("Content-Length", strconv.Itoa(len(answer.Body)))
475		}
476		f := j.current
477		f.Meta.NexusVersion, f.Meta.Edition, f.Meta.NexusNote = o.Descriptor.NexusVersion, o.Descriptor.Edition, ""
478		f.Meta.Measured, f.Meta.RecordedBy = date, recordedBy
479		if f.Meta.Record == nexusfixture.RecordPending {
480			f.Meta.Record = ""
481		}
482		f.Exchanges = []nexusfixture.Exchange{answer}
483		data = nexusfixture.Format(f)
484	
485		// What will be written is read back and checked, not what was built.
486		back, err := nexusfixture.Parse(j.campaign, filepath.Base(j.path), data)
487		if err != nil || !bytes.Equal(nexusfixture.Format(back), data) {
488			return nil, false, recordError("the answer to "+j.name+" does not read back as a fixture", "do not record this answer", err)
489		}
490		if leaks := nexusfixture.CheckLeaks(j.name, data, recordTerms(o)); len(leaks) > 0 {
491			return nil, false, recordError("the answer to "+j.name+" would leak: "+describeLeaks(leaks), "nothing was written; fix the bench or the redaction", nil)
492		}
493		if holdsTerm(header, body, recordTerms(o)) {
494			return nil, false, recordError("the answer to "+j.name+" holds a bench password or a denied term where the file would not show it", "nothing was written; do not record this answer", nil)
495		}
496		return data, sameAnswer(j.current, f), nil
497	}
498	
499	// sameAnswer reports whether the file already holds the answer: the same
500	// exchange under the same version and edition. The date, the notes and who
501	// recorded it do not count.
502	func sameAnswer(current, recorded nexusfixture.Fixture) bool {
503		if current.Meta.NexusVersion != recorded.Meta.NexusVersion || current.Meta.Edition != recorded.Meta.Edition {
504			return false
505		}
506		text := func(ex nexusfixture.Exchange) []byte {
507			return nexusfixture.Format(nexusfixture.Fixture{Exchanges: []nexusfixture.Exchange{ex}})
508		}
509		return bytes.Equal(text(current.Exchanges[0]), text(recorded.Exchanges[0]))
510	}
511	
512	var serverHeader = regexp.MustCompile(`^Nexus/(\S+) \(([A-Za-z]+)\)$`)
513	
514	// benchVersionMatches reports whether a Server header names the version and the
515	// edition of the descriptor.
516	func benchVersionMatches(server string, d Descriptor) bool {
517		m := serverHeader.FindStringSubmatch(server)
518		return m != nil && m[1] == d.NexusVersion && m[2] == d.Edition
519	}
520	
521	// declaresJSON reports whether a Content-Type is JSON.
522	func declaresJSON(contentType string) bool {
523		media, _, err := mime.ParseMediaType(contentType)
524		return err == nil && (media == "application/json" || strings.HasSuffix(media, "+json"))
525	}
