251	// descriptorDiffs lists the fields of the descriptor that the parameters of
252	// this run would write differently. The hosts and the versions are left out:
253	// they come from the cluster, not from the parameters. So is the dataset, which
254	// the parameters know nothing of.
255	func descriptorDiffs(d nexusbench.Descriptor, p nexusbench.Params) []string {
256		want := nexusbench.BuildDescriptor(p, nexusbench.DeployResult{}, nexusbench.ProvisionResult{}, nexusbench.SeedResult{})
257		fields := []struct{ name, got, want string }{
258			{"context", d.KubeContext, want.KubeContext},
259			{"namespace", d.Namespace, want.Namespace},
260			{"image", d.Image, want.Image},
261			{"http nodePort", strconv.Itoa(d.REST.NodePort), strconv.Itoa(want.REST.NodePort)},
262			{"docker nodePort", dockerPort(d), dockerPort(want)},
263			{"upstream URL", upstreamURL(d), upstreamURL(want)},
264			{"upstream image", d.Upstream.Image, want.Upstream.Image},
265			{"anonymous access", anonymous(d), anonymous(want)},
266		}
267		var diffs []string
268		for _, f := range fields {
269			if f.got != f.want {
270				diffs = append(diffs, fmt.Sprintf("%s: descriptor %s, current %s", f.name, f.got, f.want))
271			}
272		}
273		return diffs
274	}
